    "summary": "أثبت هذا الاسم في الدليل بقدر ما تسمح به مادة النسب المستخدمة وبالموضع الذي يظهر فيه داخل المشجرة. لم أضف وصفاً تاريخياً أو جغرافياً مستقلاً عندما لم أجد ما يكفي لصياغة مسؤولة.",
