    "qudaa-bahra": lineageRecord("qudaa-bahra", "بهراء", "قضاعة ← الحافي ← عمرو ← بهراء", "فرع من عمرو بن الحافي في كتب النسب، ومن أشهر المنسوبين إليه المقداد بن عمرو.", { geography: "تذكر المصادر الجغرافية فروعًا من بهراء في بلاد الشام، ولا سيما نواحي حمص والساحل في عصور لاحقة.", figures: ["المقداد بن عمرو"], sources: [ibnHazmQudaa, { ...hamdani, url: "https://shamela.ws/book/12521/132" }] }),
