    "qudaa-sud": lineageRecord("qudaa-sud", "سود", "قضاعة ← الحافي ← أسلم ← سود", "حلقة نسبية بين أسلم وليث في ترتيب ابن حزم.", { branches: ["ليث"], sources: [ibnHazmAslam] }),
