    "qudaa-jarm": lineageRecord("qudaa-jarm", "جرم", "قضاعة ← الحافي ← عمران ← حلوان ← ربان ← جرم", "فرع قضاعي، ومن أشهر أعلامه عمرو بن سلمة الجرمي.", { geography: "ذكر الهمداني جماعات من جرم في اليمامة والبصرة والعقيق وحضرموت ومواضع بين صنعاء ومأرب.", figures: ["عمرو بن سلمة الجرمي"], sources: [ibnHazmImran, { ...hamdani, url: "https://shamela.ws/book/12521/163" }] }),
