      summary: "عروة بن مسعود الثقفي من سادات ثقيف، حضر مفاوضات الحديبية ممثلًا لقريش، ثم أسلم وعاد إلى قومه يدعوهم.",
      geography: "ارتبط بالطائف ومكة، وورد خبره في الحديبية بالمدينة وما حولها.", branches: [], figures: [],
