      lineage: "ربيعة ← عبد القيس", branchId: branchIds.abdqays,
      summary: "المنذر بن عائذ، المعروف بأشج عبد القيس، من سادات وفد عبد القيس، واشتهر بقول النبي ﷺ له إن فيه خصلتين يحبهما الله: الحلم والأناة.",
      geography: "قدم من إقليم البحرين التاريخي في شرق الجزيرة ضمن وفد عبد القيس.", branches: [], figures: [],
      history: "يمثل خبره جانبًا من الصلات المبكرة بين المدينة وقبائل شرق الجزيرة، ومن مكانة وفد عبد القيس في كتب الحديث والسيرة.",
