      lineage: "ربيعة ← عبد القيس", branchId: branchIds.abdqays,
      summary: "الجارود العبدي، ويختلف في اسمه الكامل، كان سيدًا في عبد القيس، قدم في الوفد فأسلم وثبت على الإسلام زمن الردة.",
      geography: "ارتبط بعبد القيس في إقليم البحرين التاريخي، ثم تذكر الأخبار خروجه في الفتوح.", branches: [], figures: [],
      history: "تظهر أهميته في موقفه من الردة وفي تثبيت قومه، مع اختلاف كتب التراجم في بعض تفاصيل اسمه ووفاته.",
      status: "", notes: "اختلاف اسمه الكامل مذكور في كتب التراجم؛ لذلك عُرض بالاسم الأشهر: الجارود العبدي.", sources: [siyar], aliases: ["الجارود العبدي", "بشر بن المعلى"], featured: true
