      verse: { text: "لخولة أطلال ببرقة ثهمد\nتلوح كباقي الوشم في ظاهر اليد\n\nوقوفا بها صحبي علي مطيهم\nيقولون لا تهلك أسى وتجلد\n\nكأن حدوج المالكية غدوة\nخلايا سفين بالنواصف من دد", source: "ديوان طرفة بن العبد، شرح الأعلم الشنتمري، تحقيق درية الخطيب ولطفي الصقال، مطبعة دار الكتاب، دمشق، 1975م." },
