  Object.assign(guide, figures);
  document.querySelectorAll("#page-adnan .adnan-figure-groups .name-list > span").forEach(element => {
    const id = figureIdByName.get(element.textContent.trim());
    if (id) element.dataset.guideId = id;
  });
