      history: "عُرف بقوة الهجاء وسرعة الجواب، ثم سخّر شعره للدفاع عن الإسلام. وتوضح الأبيات المختارة أن دفاعه عن النبي ﷺ جعله دفاعًا عن العرض والنسب معًا.",
      verse: { text: "هجوت محمدًا فأجبت عنه\nوعند الله في ذاك الجزاء\n\nهجوت محمدًا برًا حنيفًا\nرسول الله شيمته الوفاء\n\nفإن أبي ووالده وعرضي\nلعرض محمد منكم وقاء", source: "ديوان حسان بن ثابت، تحقيق وتعليق وليد عرفات، دار صادر، بيروت، الطبعة الأولى، 2006م." },
      branchId: "khazraj", sources: [siyar(2495), hassanDiwan], aliases: ["حسان بن ثابت الأنصاري"], featured: true
