      lineage: "كهلان ← الأزد ← أزد عُمان ← اليحمد",
      summary: "أبو الشعثاء جابر بن زيد الأزدي اليحمدي من كبار التابعين وفقهاء البصرة، أخذ العلم عن ابن عباس وعائشة وابن عمر وغيرهم.",
