  const addFigureToBranch = (branchId, figureName) => {
    if (!guide[branchId]) return;
    guide[branchId].figures = [...new Set([...(guide[branchId].figures || []), figureName])];
  };
  addFigureToBranch("madhhij", "المتنبي");
  addFigureToBranch("tayy", "أبو تمام");
  addFigureToBranch("tayy", "البحتري");
  addFigureToBranch("qudaa", "أبو العلاء المعري");

  const enrich = (id, summary, history) => {
    if (!guide[id]) return;
    guide[id] = { ...guide[id], summary, history };
  };
  enrich("abikarib-asad", "أبو كرب أسعد ملك حميري موثق بالنقوش في أواخر القرن الرابع وأوائل الخامس الميلادي، وكان من أبرز ملوك مرحلة اتساع نفوذ حمير إلى وسط الجزيرة العربية.", "تسميه الروايات العربية تبعًا أسعد الكامل، بينما تثبت النقوش اسمه وألقابه الملكية وحملاته بدرجة أوثق. ويرتبط عهده أيضًا بترسخ التوحيد في الصياغة الدينية الرسمية لحمير.");
  enrich("yusuf-asar", "يوسف أسأر يثأر آخر ملوك حمير المستقلين، ويعرف في المصادر العربية بذي نواس. تثبته النقوش ملكًا خاض حربًا ضد الأحباش وحلفائهم في أوائل القرن السادس الميلادي.", "ارتبط اسمه بأحداث نجران سنة 523م، ثم أدى الصراع إلى تدخل أكسوم وسقوط حكمه. وتُقرأ سيرته من النقوش والمصادر القريبة من الحدث، لا من الروايات المتأخرة وحدها.");
  enrich("miqdad-amr", "المقداد بن عمرو البهراني القضاعي من السابقين إلى الإسلام ومن فرسان الصحابة، واشتهر باسم المقداد بن الأسود بسبب حلفه وتبنّي الأسود بن عبد يغوث له في الجاهلية.", "هاجر وشهد بدرًا والمشاهد بعدها، وكان من أصحاب المواقف المشهورة في الثبات والنصرة. وتوضح ترجمته الفرق بين النسب الأصلي والاسم الذي شاع بسبب الحلف.");
  enrich("kab-ujra", "كعب بن عجرة صحابي مدني يُذكر في بلي نسبًا، واشتهر في كتب الحديث بالأنصاري السالمي لحلفه وإقامته. شهد الحديبية وروى عنه جماعة.", "نزلت في شأن أذاه من هوام رأسه رخصة الفدية للمحرم، فصار حديثه أصلًا في باب من أحكام الحج. وعاش إلى نحو سنة 52هـ.");
  enrich("uqba-amir", "عقبة بن عامر الجهني صحابي ومقرئ وفقيه، لازم القرآن والحديث، وشارك في فتح مصر ثم تولى إمارتها لمعاوية بن أبي سفيان.", "عُرف بالقراءة والفرائض والرمي، وروى أحاديث كثيرة. وتوفي بمصر نحو سنة 58هـ بعد حياة جمعت بين العلم والإدارة والعمل العسكري.");
  enrich("dihya-kalbi", "دحية بن خليفة الكلبي صحابي من بني كلب، عُرف بحسن الهيئة، واختاره النبي ﷺ لحمل رسالته إلى هرقل إمبراطور الروم.", "شهد عددًا من المشاهد بعد بدر، وكان من رسل النبي ﷺ إلى الملوك. ثم ارتبطت أخباره ببلاد الشام حيث نزل في أواخر حياته.");
  enrich("zayd-haritha", "زيد بن حارثة الكلبي من السابقين إلى الإسلام، وكان مولى النبي ﷺ وحِبَّه، وهو الصحابي الوحيد الذي ورد اسمه صريحًا في القرآن الكريم.", "قاد عددًا من السرايا، ثم جعله النبي ﷺ أول أمراء جيش مؤتة، فاستشهد فيها سنة 8هـ. وتجمع سيرته بين الانتماء إلى كلب ومكانته الخاصة في بيت النبوة.");
  enrich("amr-salama-jarmi", "عمرو بن سلمة الجرمي من صغار الصحابة، كان يتلقى القرآن من الركبان القادمين إلى قومه حتى صار أكثرهم حفظًا، فقدموه لإمامتهم وهو غلام.", "ترد قصته في صحيح البخاري، وهي مثال مبكر على أثر حفظ القرآن في التعليم والإمامة داخل القبائل البعيدة عن المدينة.");
  enrich("abu-musa-ashari", "أبو موسى عبد الله بن قيس الأشعري صحابي وفقيه وقارئ من قبيلة الأشعر، عُرف بحسن الصوت بالقرآن وبالعلم والقضاء.", "قدم من اليمن، وشارك في الفتوح، وتولى البصرة والكوفة في مراحل من صدر الإسلام. وروى عنه عدد كبير من الصحابة والتابعين.");
  enrich("tufayl-amr-dawsi", "الطفيل بن عمرو الدوسي صحابي وسيد في قومه وشاعر خطيب، لقي النبي ﷺ في مكة فأسلم ثم عاد يدعو دوسًا إلى الإسلام.", "قدم بعد ذلك بمن أسلم من قومه إلى المدينة، وشارك في هدم صنم ذي الكفين، ثم استشهد في حروب الردة على أشهر الروايات.");

  delete guide.ashath;
  delete guide["amr-madi"];

  if (typeof document !== "undefined") {
    document.querySelectorAll("#page-qahtan .qahtan-figures-section [data-guide-id]").forEach(element => {
      const id = element.dataset.guideId;
      if (!guide[id]) element.removeAttribute("data-guide-id");
    });
  }
